import { randomBytes } from 'node:crypto';
import { and, asc, eq, gt, ne, sql } from 'drizzle-orm';
import { userKeys } from '../db/schema.js';
import type { Db } from '../types.js';
import type { Keyring } from './keyring.js';
import { contextBytes, open, seal } from './seal.js';

/**
 * Where a sealed value lives (C-3). The blob opens only under the same table,
 * owner and row, so a copy moved to another user's row or another table fails.
 * `rowId` is generated by the application before insert.
 */
export interface SealContext {
  table: string;
  userId: string;
  rowId: string;
}

type Reader = Pick<Db, 'select'>;
type ReadWriter = Pick<Db, 'select' | 'insert'>;

/**
 * Key id written into blobs sealed with a user's data key. The ring key that
 * wraps the data key is recorded in `user_keys.key_id`, not here, so rotating
 * the ring never touches health columns.
 */
const USER_KEY_ID = 'u1';

function contextFor(ctx: SealContext): Buffer {
  if (!ctx.table || !ctx.userId || !ctx.rowId) throw new Error('sealFor: context needs table, userId and rowId');
  return contextBytes('kq/v1', ctx.table, ctx.userId, ctx.rowId);
}

/** The wrapped key is itself bound to its owner, so swapping wrapped keys between users fails too. */
const wrapContext = (userId: string) => contextBytes('kq/v1', 'user_keys', userId);

function wrap(keyring: Keyring, userId: string, dataKey: Buffer): Buffer {
  return seal(dataKey.toString('base64'), keyring.active, keyring.activeId, wrapContext(userId));
}

function unwrap(keyring: Keyring, userId: string, wrapped: Buffer): Buffer {
  const key = Buffer.from(open<string>(wrapped, keyring.all, wrapContext(userId)), 'base64');
  if (key.length !== 32) throw new Error('user key is malformed');
  return key;
}

async function loadUserKey(db: Reader, keyring: Keyring, userId: string): Promise<Buffer | null> {
  const [row] = await db.select({ wrapped: userKeys.wrapped }).from(userKeys).where(eq(userKeys.userId, userId));
  return row ? unwrap(keyring, userId, row.wrapped) : null;
}

/** The user's data key, created (and wrapped by the active ring key) on first use. Safe under concurrency. */
async function userKey(db: ReadWriter, keyring: Keyring, userId: string, now?: Date): Promise<Buffer> {
  const existing = await loadUserKey(db, keyring, userId);
  if (existing) return existing;
  const fresh = randomBytes(32);
  await db
    .insert(userKeys)
    .values({ userId, keyId: keyring.activeId, wrapped: wrap(keyring, userId, fresh), ...(now ? { createdAt: now } : {}) })
    .onConflictDoNothing({ target: userKeys.userId });
  // Another request may have created it first; whichever row won is the key.
  const key = await loadUserKey(db, keyring, userId);
  if (!key) throw new Error('user key vanished after insert');
  return key;
}

/**
 * Seals `value` with the owner's data key, bound to `ctx` (C-3, C-4). `now`
 * stamps a data key created here (routes pass their injected clock).
 */
export async function sealFor(db: ReadWriter, keyring: Keyring, ctx: SealContext, value: unknown, now?: Date): Promise<Buffer> {
  const aad = contextFor(ctx);
  return seal(value, await userKey(db, keyring, ctx.userId, now), USER_KEY_ID, aad);
}

/**
 * Opens a blob sealed by `sealFor` under the same context. Throws if the
 * context differs, the blob was tampered with, or the user has no data key
 * (account deleted: the data is crypto-shredded).
 */
export async function openFor<T>(db: Reader, keyring: Keyring, ctx: SealContext, sealed: Buffer): Promise<T> {
  const aad = contextFor(ctx);
  const key = await loadUserKey(db, keyring, ctx.userId);
  if (!key) throw new Error('openFor: no data key for this user (deleted account?)');
  return open<T>(sealed, { [USER_KEY_ID]: key }, aad);
}

/**
 * `openFor` for many blobs of one owner: the data key is loaded once (a player's whole progress history may hold many
 * sealed rows). The returned function opens each blob under its own context, whose `userId` must be this owner.
 * Throws, as `openFor` does, when the owner has no data key.
 */
export async function openerFor(db: Reader, keyring: Keyring, userId: string): Promise<<T>(ctx: SealContext, sealed: Buffer) => T> {
  const key = await loadUserKey(db, keyring, userId);
  if (!key) throw new Error('openFor: no data key for this user (deleted account?)');
  return <T>(ctx: SealContext, sealed: Buffer): T => {
    if (ctx.userId !== userId) throw new Error('openerFor: a blob of another user');
    return open<T>(sealed, { [USER_KEY_ID]: key }, contextFor(ctx));
  };
}

/**
 * Re-wraps every user key not yet under the active ring key (C-2 rekey), in
 * batches. Idempotent: a second run finds nothing to do. Each update matches
 * the old key id too, so a row changed concurrently is simply picked up again.
 * Throws on a row it cannot unwrap (its ring key is missing), before any data is lost.
 */
export async function rewrapUserKeys(
  db: Pick<Db, 'select' | 'update'>,
  keyring: Keyring,
  opts: { batchSize?: number } = {},
): Promise<{ rewrapped: number; remaining: number }> {
  const batchSize = opts.batchSize ?? 500;
  let rewrapped = 0;
  let after = '00000000-0000-0000-0000-000000000000';
  for (;;) {
    const batch = await db
      .select({ userId: userKeys.userId, keyId: userKeys.keyId, wrapped: userKeys.wrapped })
      .from(userKeys)
      .where(and(ne(userKeys.keyId, keyring.activeId), gt(userKeys.userId, after)))
      .orderBy(asc(userKeys.userId))
      .limit(batchSize);
    if (batch.length === 0) break;
    for (const row of batch) {
      const dataKey = unwrap(keyring, row.userId, row.wrapped);
      const updated = await db
        .update(userKeys)
        .set({ keyId: keyring.activeId, wrapped: wrap(keyring, row.userId, dataKey) })
        .where(and(eq(userKeys.userId, row.userId), eq(userKeys.keyId, row.keyId)))
        .returning({ userId: userKeys.userId });
      rewrapped += updated.length;
    }
    after = batch.at(-1)!.userId;
  }
  const [left] = await db
    .select({ n: sql<number>`count(*)::int` })
    .from(userKeys)
    .where(ne(userKeys.keyId, keyring.activeId));
  return { rewrapped, remaining: left?.n ?? 0 };
}
